"""SQL Server record IDs: UNIQUEIDENTIFIER, as uuid.UUID, generated by the application (like ObjectId).

new_id() makes "sequential" GUIDs: SQL Server sorts UNIQUEIDENTIFIER by its LAST 6 bytes first, so those
hold a clock tick that only grows in this process. New rows therefore land at the end of the clustered
primary key (no page splits), and rows inserted later sort later, as ObjectIds did. The other bytes are
random (74 random bits). In text, IDs are the canonical form "xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx".
"""
import os
import re
import threading
import time
import uuid

_CANONICAL = re.compile(r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$")
_TICK_NS = 100_000                    # 0.1 ms: 48 bits last until the year 2861
_TICK_MASK = (1 << 48) - 1
_lock = threading.Lock()
_last_tick = 0


def new_id() -> uuid.UUID:
    """A new record ID (see the module docstring)."""
    global _last_tick
    with _lock:
        tick = max(time.time_ns() // _TICK_NS, _last_tick + 1)       # strictly increasing in this process
        _last_tick = tick
    raw = bytearray(os.urandom(10) + (tick & _TICK_MASK).to_bytes(6, "big"))
    raw[6] = (raw[6] & 0x0F) | 0x80          # version 8 (RFC 9562: custom layout)
    raw[8] = (raw[8] & 0x3F) | 0x80          # RFC 9562 variant
    return uuid.UUID(bytes=bytes(raw))


def parse_id(value: str | uuid.UUID | None) -> uuid.UUID | None:
    """The ID for `value`, or None if it is missing or not a valid ID (an ID passes through unchanged).
    Text must be the canonical 36-character form (no braces, URNs or bare hex)."""
    if value is None or isinstance(value, uuid.UUID):
        return value
    return uuid.UUID(value) if isinstance(value, str) and _CANONICAL.match(value) else None


def to_id(value: str) -> uuid.UUID:
    """The ID for a string that must be one (e.g. inside a page cursor). Raises ValueError otherwise."""
    record_id = parse_id(value) if isinstance(value, str) else None
    if record_id is None:
        raise ValueError("not a record id")
    return record_id


def is_id(value: object) -> bool:
    return isinstance(value, uuid.UUID)
